- Observability, tracing, and testing best practices

## Code Example

```javascript
import { Chain, Tool, Planner } from 'langchain';
import { AgentExecutor } from 'langchain/agents';
import Redis from 'ioredis';

const redis = new Redis(process.env.REDIS_URL);

const apiTool = new Tool({
  name: 'fetch_analytics',
  description: 'Fetches user analytics from the private REST API. Input: JSON with query parameters.',
  func: async (input, runManager) => {
    const response = await fetchWithRetry(input);
    return JSON.stringify(response);
  }
});

async function fetchWithRetry(input, maxRetries = 3) {
  const baseDelay = 1000;
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      const response = await fetch('/api/analytics', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: input
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      return await response.json();
    } catch (err) {
      if (attempt === maxRetries - 1 || !isRetriable(err)) throw err;
      await sleep(baseDelay * Math.pow(2, attempt));
    }
  }
}

const cacheMiddleware = async (req, next) => {
  const cacheKey = `analytics:${JSON.stringify(req)}`;
  const cached = await redis.get(cacheKey);
  if (cached) return JSON.parse(cached);

  const result = await next();
  await redis.setex(cacheKey, 3600, JSON.stringify(result));
  return result;
};
```

## Why This Is Asked

This question assesses practical understanding of retrieval pipelines using chunking, embeddings, and vector stores, along with knowledge of real-world metrics for evaluating RAG systems.

## Key Concepts

- Retrieval Augmented Generation (RAG)
- Document chunking strategies (size, overlap, and trade-offs)
- Embedding models and vector stores
- Two-stage retrieval (dense retrieval + reranking)
- Evaluation metrics: recall@K and latency benchmarks

## Code Example

```javascript
// Minimal chunking sketch (size=512, overlap=128)
function chunkText(text, size = 512, overlap = 128) {
  const chunks = [];
  let start = 0;
  while (start < text.length) {
    const end = start + size;
    chunks.push(text.slice(start, end));
    start += size - overlap;
  }
  return chunks;
}

// Two-step retrieval call
async function retrieve(query, topK = 10) {
  const queryEmbedding = await embedModel.embed(query);
  const initialResults = await vectorStore.search(queryEmbedding, topK * 3);
  const reranked = await reranker.rerank(query, initialResults, topK);
  return reranked;
}
```

